from pathlib import Path
p=Path('src/parkweave/web.html');s=p.read_text()
needle='<section id="opp-plan-preview" hidden>'
markup='''<section id="plan-source-conflict-panel" class="combination-panel"><h4>本计划的人工协调说明与资料来源差异</h4><p>人工协调说明独立于资料事实和服务合同。来源候选仅取此事项实际材料目录正文；机会提示不能作为事实或授权。来源改变后须明确处理，原业务核验仍从原入口完成。</p><button id="plan-source-conflict-read" type="button">读取人工说明与当前资料</button><button id="plan-source-conflict-recover" type="button">只读核对原说明操作</button><label>用于处理的当前机会<select id="plan-source-conflict-card"><option value="">只读取与编辑人工说明</option></select></label><p id="plan-source-conflict-status" role="status" aria-live="polite"></p><div id="plan-source-conflict-result"></div><label>人工协调说明<textarea id="plan-source-conflict-note" maxlength="4000"></textarea></label><label>本次编辑或处理说明<textarea id="plan-source-conflict-reason" maxlength="1000"></textarea></label><label><input id="plan-source-conflict-confirm" type="checkbox">我已核对原文、来源版本及人工锁，明确保存本次选择</label><button id="plan-source-conflict-edit" type="button" disabled>明确保存人工协调说明</button><button id="plan-source-conflict-keep" type="button" disabled>保留人工修改</button><button id="plan-source-conflict-accept" type="button" disabled>接受当前来源修改</button><button id="plan-source-conflict-defer" type="button" disabled>暂不处理，保留待办</button><p>保留或暂不处理不会恢复旧核验。接受来源也不会自动解锁、采纳计划或核验；请先按原规则明确解锁，再分别采纳与核验。</p><details><summary>人工说明及处置历史</summary><div id="plan-source-conflict-history"></div></details></section>'''
assert s.count(needle)==1;s=s.replace(needle,markup+needle);p.write_text(s)
